<template>
  <div class="user-settings-container h-full">
    <div class="flex h-full flex-col">
      <h2 class="mb-2 text-2xl font-bold">{{ $t('userSettings.title') }}</h2>
      <Divider class="mb-3" />

      <!-- Loading state -->
      <div v-if="loading" class="flex items-center justify-center py-8">
        <i class="pi pi-spin pi-spinner text-2xl text-muted" />
      </div>

      <!-- Logged in -->
      <div v-else-if="userInfo" class="flex flex-col gap-4">
        <!-- User header with avatar and name -->
        <div class="flex items-center gap-4">
          <div
            class="flex size-14 items-center justify-center rounded-full text-xl font-bold text-white"
            :class="userInfo.isAdmin ? 'bg-orange-600' : 'bg-blue-600'"
          >
            {{ userInitial }}
          </div>
          <div class="flex flex-col">
            <div class="flex items-center gap-2">
              <span class="text-lg font-semibold">{{ userInfo.username }}</span>
              <span
                v-if="userInfo.isAdmin"
                class="rounded bg-orange-100 px-1.5 py-0.5 text-xs font-medium text-orange-700"
              >
                Admin
              </span>
            </div>
            <span class="text-sm text-muted">ID: {{ userInfo.userId }}</span>
          </div>
        </div>

        <Divider />

        <!-- User details -->
        <div class="flex flex-col gap-3">
          <div class="flex flex-col gap-0.5">
            <h3 class="font-medium">
              {{ $t('userSettings.name') }}
            </h3>
            <div class="text-muted">
              {{ userInfo.username || $t('userSettings.notSet') }}
            </div>
          </div>

          <div class="flex flex-col gap-0.5">
            <h3 class="font-medium">
              {{ $t('userSettings.provider') }}
            </h3>
            <div class="flex items-center gap-1 text-muted">
              <i class="pi pi-key" />
              Local
              <Button
                v-tooltip="{
                  value: $t('userSettings.updatePassword'),
                  showDelay: 300
                }"
                variant="muted-textonly"
                size="icon-sm"
                @click="dialogService.showUpdatePasswordDialog()"
              >
                <i class="pi pi-pen-to-square" />
              </Button>
            </div>
          </div>

          <div class="flex flex-col gap-0.5">
            <h3 class="font-medium">Level</h3>
            <div class="text-muted">
              {{ levelLabel }}
            </div>
          </div>

          <div class="flex flex-col gap-0.5">
            <h3 class="font-medium">Status</h3>
            <div class="flex items-center gap-1.5">
              <span
                class="inline-block size-2 rounded-full"
                :class="userInfo.isActive ? 'bg-green-500' : 'bg-red-500'"
              />
              <span class="text-muted">
                {{ userInfo.isActive ? 'Active' : 'Inactive' }}
              </span>
            </div>
          </div>

          <div class="flex flex-col gap-0.5">
            <h3 class="font-medium">Registered</h3>
            <div class="text-muted">
              {{ formatDate(userInfo.createdAt) }}
            </div>
          </div>

          <div class="flex flex-col gap-0.5">
            <h3 class="font-medium">Last Login</h3>
            <div class="text-muted">
              {{ formatDate(userInfo.lastLogin) }}
            </div>
          </div>
        </div>

        <div class="mt-4 flex flex-col gap-2">
          <Button class="w-32" variant="secondary" @click="handleSignOut">
            <i class="pi pi-sign-out" />
            {{ $t('auth.signOut.signOut') }}
          </Button>
        </div>
      </div>

      <!-- Not logged in -->
      <div v-else class="flex flex-col items-center gap-4 py-8">
        <i class="pi pi-user text-4xl text-muted" />
        <p class="text-muted">{{ $t('g.notLoggedIn') }}</p>
        <Button @click="handleSignIn">
          <i class="pi pi-sign-in" />
          {{ $t('login.login') }}
        </Button>
      </div>
    </div>
  </div>
</template>

<script setup lang="ts">
import { computed, onMounted, ref } from 'vue'
import Divider from 'primevue/divider'

import Button from '@/components/ui/button/Button.vue'
import { useUserStore } from '@/stores/userStore'
import { useDialogService } from '@/services/dialogService'
import { api } from '@/scripts/api'

interface UserInfo {
  userId: string
  username: string
  level?: number
  isAdmin?: boolean
  isActive?: boolean
  createdAt?: string
  lastLogin?: string
}

const userStore = useUserStore()
const dialogService = useDialogService()

const loading = ref(true)
const userInfo = ref<UserInfo | null>(null)

const userInitial = computed(() =>
  userInfo.value?.username?.charAt(0).toUpperCase() ?? '?'
)

const levelLabel = computed(() => {
  const level = userInfo.value?.level
  if (level === 3) return 'Administrator'
  if (level === 2) return 'Advanced'
  return 'Standard'
})

function formatDate(dateStr?: string): string {
  if (!dateStr) return 'N/A'
  try {
    const date = new Date(dateStr)
    return date.toLocaleDateString(undefined, {
      year: 'numeric',
      month: 'short',
      day: 'numeric',
      hour: '2-digit',
      minute: '2-digit'
    })
  } catch {
    return dateStr
  }
}

async function fetchUserInfo() {
  loading.value = true
  try {
    // Always fetch fresh data from API (includes extended user info)
    const config = await api.getUserConfig()
    if (config?.users?.length) {
      const apiUser = config.users[0]
      userInfo.value = {
        userId: apiUser.userId,
        username: apiUser.username,
        level: (apiUser as any).level,
        isAdmin: (apiUser as any).isAdmin,
        isActive: (apiUser as any).isActive,
        createdAt: (apiUser as any).createdAt,
        lastLogin: (apiUser as any).lastLogin,
      }
      // Also update userStore for consistency
      if (!userStore.currentUserId) {
        userStore.login({
          userId: apiUser.userId,
          username: apiUser.username
        })
      }
    } else {
      userInfo.value = null
    }
  } catch (err) {
    console.error('Failed to fetch user info:', err)
    userInfo.value = null
  } finally {
    loading.value = false
  }
}

onMounted(() => {
  void fetchUserInfo()
})

async function handleSignOut() {
  await fetch('/api/logout', { method: 'POST' })
  await userStore.logout()
  userInfo.value = null
  window.location.href = '/login'
}

function handleSignIn() {
  window.location.href = '/login'
}
</script>
